"""Deterministic generation for explicit combinational and temporal profiles.

Generation establishes no acceptance claim. ``check_synthetic_candidate`` runs
the separate model runner and finite-history response checker afterwards.
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping
from dataclasses import dataclass, replace
from typing import ClassVar

from biocompiler.errors import UnsupportedBehaviorError
from biocompiler.ir.components import ComponentLock
from biocompiler.ir.intent import freeze_json, thaw_json
from biocompiler.ir.mechanism import MechanismNode, MechanismProgram
from biocompiler.ir.serialization import JsonArtifact, fields, names, require
from biocompiler.registry.synthetic import (
    SYNTHETIC_PROFILE_VERSION,
    TEMPORAL_PROFILE_VERSION,
    catalog_for_profile,
)
from biocompiler.semantics.evaluator import InputFrame
from biocompiler.semantics.realization import Observable
from biocompiler.semantics.types import BOOLEAN, DURATION, TypeSpec, decode_binding
from biocompiler.synthesis.policy import STRATEGIES, policy_for_request
from biocompiler.verification.evidence import (
    CheckDiagnostic,
    CheckOutcome,
    CheckResult,
    DependencySnapshot,
)
from biocompiler.verification.realization import (
    InputBinding,
    ObservationMap,
    OutputBinding,
    check_realization,
    realization_dependencies,
)

from biocompiler.verification.admission import admission_for_target

GENERATOR_VERSION = "biocompiler.synthetic.generator.v0.4"
SYNTHETIC_CHECKER_VERSION = "biocompiler.synthetic.acceptance.v0.5"


def _identity(value, label):
    require(
        isinstance(value, str)
        and len(value) == 64
        and all(char in "0123456789abcdef" for char in value),
        f"{label} must be a SHA-256 identity.",
    )


@dataclass(frozen=True)
class SyntheticGeneratorConfig(JsonArtifact):
    """An exhaustive generation policy; no stochastic search is performed."""

    profile_version: str = SYNTHETIC_PROFILE_VERSION
    generator_version: str = GENERATOR_VERSION
    catalog_fingerprint: str | None = None
    witness_selection: str = "closed_band_lower_endpoint"
    conjunction_strategy: str = "native"
    schema_version: ClassVar[str] = "biocompiler.synthetic_generator_config.v0.3"

    def __post_init__(self):
        catalog = catalog_for_profile(self.profile_version)
        if self.catalog_fingerprint is None:
            object.__setattr__(self, "catalog_fingerprint", catalog.fingerprint)
        require(
            self.generator_version == GENERATOR_VERSION,
            "Unsupported synthetic generator version.",
        )
        require(
            self.catalog_fingerprint == catalog.fingerprint,
            "The selected synthetic catalog is unavailable or stale.",
        )
        require(
            self.witness_selection == "closed_band_lower_endpoint",
            "Unsupported response witness selection policy.",
        )
        require(
            self.conjunction_strategy in STRATEGIES, "Unsupported conjunction strategy."
        )

    def to_dict(self):
        return {
            "schema_version": self.schema_version,
            "profile_version": self.profile_version,
            "generator_version": self.generator_version,
            "catalog_fingerprint": self.catalog_fingerprint,
            "witness_selection": self.witness_selection,
            "conjunction_strategy": self.conjunction_strategy,
        }

    @classmethod
    def from_dict(cls, data: Mapping):
        fields(
            data,
            {
                "schema_version",
                "profile_version",
                "generator_version",
                "catalog_fingerprint",
                "witness_selection",
                "conjunction_strategy",
            },
            cls.__name__,
        )
        require(
            data["schema_version"] == cls.schema_version,
            "Unsupported generator-config schema.",
        )
        _identity(data["catalog_fingerprint"], "Catalog fingerprint")
        return cls(
            **{key: value for key, value in data.items() if key != "schema_version"}
        )


@dataclass(frozen=True)
class SyntheticCandidate(JsonArtifact):
    request_fingerprint: str
    mechanism: MechanismProgram
    observation_map: ObservationMap
    source_map: Mapping[str, tuple[str, ...]]
    behavior_requirement_ids: Mapping[str, tuple[str, ...]]
    component_locks: tuple[ComponentLock, ...]
    generator_config: SyntheticGeneratorConfig
    schema_version: ClassVar[str] = "biocompiler.synthetic_candidate.v0.4"

    def __post_init__(self):
        _identity(self.request_fingerprint, "Request fingerprint")
        require(
            isinstance(self.mechanism, MechanismProgram),
            "Candidate requires a mechanism.",
        )
        require(
            isinstance(self.observation_map, ObservationMap),
            "Candidate requires an observation map.",
        )
        require(
            isinstance(self.generator_config, SyntheticGeneratorConfig),
            "Candidate requires a generator configuration.",
        )
        node_ids = {node.id for node in self.mechanism.nodes}
        for key in ("source_map", "behavior_requirement_ids"):
            value = getattr(self, key)
            require(
                isinstance(value, Mapping) and set(value) == node_ids,
                f"{key} must cover every mechanism node exactly once.",
            )
            normalized = {ref: names(items, key) for ref, items in value.items()}
            if key == "source_map":
                require(
                    all(normalized.values()),
                    "Every mechanism node needs source correspondence.",
                )
            object.__setattr__(self, key, freeze_json(normalized))
        require(
            isinstance(self.component_locks, (tuple, list))
            and all(isinstance(item, ComponentLock) for item in self.component_locks),
            "Candidate requires component locks.",
        )
        locks = tuple(sorted(self.component_locks, key=lambda item: item.node_id))
        require(
            len({item.node_id for item in locks}) == len(locks)
            and {item.node_id for item in locks} == node_ids,
            "Component locks must cover every mechanism node exactly once.",
        )
        object.__setattr__(self, "component_locks", locks)

    def to_dict(self):
        return {
            "schema_version": self.schema_version,
            "intended_use": "software_test",
            "human_therapeutic_admission": "not_admitted",
            "request_fingerprint": self.request_fingerprint,
            "mechanism": self.mechanism.to_dict(),
            "observation_map": self.observation_map.to_dict(),
            "source_map": thaw_json(self.source_map),
            "behavior_requirement_ids": thaw_json(self.behavior_requirement_ids),
            "component_locks": [item.to_dict() for item in self.component_locks],
            "generator_config": self.generator_config.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: Mapping):
        fields(
            data,
            {
                "schema_version",
                "intended_use",
                "human_therapeutic_admission",
                "request_fingerprint",
                "mechanism",
                "observation_map",
                "source_map",
                "behavior_requirement_ids",
                "component_locks",
                "generator_config",
            },
            cls.__name__,
        )
        require(
            data["schema_version"] == cls.schema_version
            and data["intended_use"] == "software_test"
            and data["human_therapeutic_admission"] == "not_admitted",
            "Unsupported candidate schema.",
        )
        require(
            isinstance(data["component_locks"], (tuple, list)),
            "Component locks must be an array.",
        )
        return cls(
            data["request_fingerprint"],
            MechanismProgram.from_dict(data["mechanism"]),
            ObservationMap.from_dict(data["observation_map"]),
            data["source_map"],
            data["behavior_requirement_ids"],
            tuple(ComponentLock.from_dict(item) for item in data["component_locks"]),
            SyntheticGeneratorConfig.from_dict(data["generator_config"]),
        )


def _request(request):
    # Local import keeps the generator independent of authoring module imports.
    from biocompiler.compiler.request import RealizationRequest

    if not isinstance(request, RealizationRequest):
        raise TypeError("Synthetic generation requires a frozen RealizationRequest.")
    return (
        request.behavior,
        request.contract,
        request.domain,
        request.build_request.target,
    )


def _generate_synthetic(
    request, *, config: SyntheticGeneratorConfig | None = None
) -> SyntheticCandidate:
    """Generate digital operators from an authorized Behavior artifact.

    Supported guards are explicit qualitative observations, scalar observations
    compared to literals/bound parameters, and Boolean and/or/not combinations.
    Signature wrappers preserve their expression. Ongoing ``rest``, ``eliminate``
    and ``engulf`` requests become authored abstract response measurements.
    Response levels are compiler-selected witnesses in the authored bands, not
    new biological guarantees; deadlines are never changed or inferred.
    """
    behavior, contract, domain, target = _request(request)
    config = config if config is not None else SyntheticGeneratorConfig()
    require(
        isinstance(config, SyntheticGeneratorConfig),
        "Expected a synthetic generator configuration.",
    )
    catalog = catalog_for_profile(config.profile_version)
    temporal = config.profile_version == TEMPORAL_PROFILE_VERSION
    source_nodes = {node.id: node for node in behavior.nodes}

    def reject(message, node=None):
        raise UnsupportedBehaviorError(
            message,
            node_id=node.id if node else None,
            source=node.source if node else None,
        )

    admission = admission_for_target(target, boundary="selection")
    if admission.decision != "software_only":
        reject(
            "Human therapeutic use is not admitted: " + "; ".join(admission.diagnostics)
        )

    if request.build_request.artifact_scope != "synthetic_realization":
        reject(
            "Synthetic generation requires the explicit synthetic_realization artifact scope."
        )
    policy_for_request(request, config.profile_version)
    if len(behavior.find(kind="role")) != 1 or domain.role != contract.role:
        reject("The synthetic profile requires exactly one executing role.")
    if domain.max_contacts is None:
        reject("The synthetic profile requires an explicit finite max_contacts bound.")
    if target is None or "synthetic_signal_graph" not in target.capabilities:
        reject(
            "Synthetic generation requires a target with synthetic_signal_graph capability."
        )
    if "abstract" not in target.compartments:
        reject("Synthetic generation requires the abstract compartment.")
    if set(domain.required_capabilities) - set(target.capabilities):
        reject("The target does not provide all operating-domain capabilities.")
    supported = {
        "role",
        "scope",
        "signal",
        "qualitative",
        "literal",
        "parameter",
        "and",
        "or",
        "not",
        "compare",
        "signature",
        "rule",
        "action.rest",
        "action.eliminate",
        "action.engulf",
    }
    if temporal:
        supported.update(
            {"held_for", "became_true", "memory", "memory.is_set", "action.pulse"}
        )
    for node in behavior.nodes:
        if node.kind not in supported:
            reject(
                f"Operation {node.kind!r} is unsupported by {config.profile_version}; temporal/state semantics are never approximated.",
                node,
            )
        if (
            node.kind == "rule"
            and node.attributes["trigger"] != "condition"
            and not temporal
        ):
            reject(
                "The combinational synthetic profile requires condition-triggered rules.",
                node,
            )
        if node.kind == "rule" and node.attributes["trigger"] == "event":
            if any(source_nodes[ref].kind != "action.pulse" for ref in node.inputs[2:]):
                reject("Synthetic event rules require explicit-duration pulses.", node)
    installed = {
        (rule.id, action)
        for rule in behavior.find(kind="rule")
        for action in rule.inputs[2:]
    }
    if installed != {
        (item.rule_id, item.specification_id) for item in contract.requirements
    }:
        reject("A response contract must cover every installed action exactly once.")
    if contract.behavior_fingerprint != behavior.fingerprint:
        reject("The response contract identifies a different Behavior artifact.")
    for item in (*domain.inputs, *contract.requirements):
        if item.observable.compartment != "abstract":
            reject("Synthetic components support only the abstract compartment.")

    generated: dict[str, MechanismNode] = {}
    source_map = {}
    behavior_requirements = {}
    input_map = {}
    observed = set()
    domain_inputs = {(item.signal_id, item.field): item for item in domain.inputs}
    expression_cache = {}
    response_sources = {
        item.id: set(behavior.source_links[item.rule_id])
        for item in contract.requirements
    }

    def add(
        ref,
        kind,
        dtype,
        scope,
        sources,
        inputs=(),
        attributes=None,
        output=None,
        response_ids=None,
    ):
        lineage = tuple(
            sorted(
                {
                    ancestor
                    for source in sources
                    for ancestor in behavior.source_links[source]
                }
            )
        )
        response_ids = tuple(
            sorted(
                response_ids
                if response_ids is not None
                else (
                    item.id
                    for item in contract.requirements
                    if set(sources) & response_sources[item.id]
                )
            )
        )
        generated[ref] = MechanismNode(
            ref,
            kind,
            output or Observable(f"synthetic.{ref}", dtype, domain.role, scope=scope),
            tuple(inputs),
            attributes or {},
            response_ids,
        )
        source_map[ref] = lineage
        behavior_requirements[ref] = tuple(
            sorted(
                {
                    requirement
                    for source in sources
                    for requirement in source_nodes[source].requirement_ids
                }
            )
        )
        return ref

    def observe(signal_id, field, source_id):
        key = (signal_id, field)
        if key not in domain_inputs:
            reject(
                f"Missing explicit operating-domain observation {key!r}.",
                source_nodes[source_id],
            )
        item, node = domain_inputs[key], source_nodes[signal_id]
        dtype = TypeSpec.from_dict(node.data_type) if field == "value" else BOOLEAN
        scope = "contact" if node.contact_bound else "cell"
        if item.observable.scope != scope or not item.observable.dtype.compatible(
            dtype
        ):
            reject(
                "The operating-domain observation has incorrect type or contact scope.",
                node,
            )
        observed.add(key)
        if key not in input_map:
            ref = f"input:{signal_id}:{field}"
            input_map[key] = add(
                ref, "input", dtype, scope, (source_id,), output=item.observable
            )
        else:
            ref = input_map[key]
            source_map[ref] = tuple(
                sorted(set(source_map[ref]) | set(behavior.source_links[source_id]))
            )
            behavior_requirements[ref] = tuple(
                sorted(
                    set(behavior_requirements[ref])
                    | set(source_nodes[source_id].requirement_ids)
                )
            )
            generated[ref] = replace(
                generated[ref],
                requirement_ids=tuple(
                    sorted(
                        set(generated[ref].requirement_ids)
                        | {
                            item.id
                            for item in contract.requirements
                            if source_id in response_sources[item.id]
                        }
                    )
                ),
            )
        return input_map[key]

    def duration(ref):
        node = source_nodes[ref]
        if node.kind not in {"literal", "parameter"}:
            reject("Synthetic durations must be bound design-time constants.", node)
        value = node.attributes["value" if node.kind == "literal" else "default"]
        value = decode_binding(value, DURATION)
        if value.canonical_value <= 0:
            reject("Synthetic durations must be positive.", node)
        return value.to_dict()

    def aggregate(ref, output_id, sources):
        if generated[ref].scope == "cell":
            return ref
        return add(output_id, "any_contact", BOOLEAN, "cell", sources, inputs=(ref,))

    def expression(ref):
        if ref in expression_cache:
            return expression_cache[ref]
        node = source_nodes[ref]
        scope = "contact" if node.contact_bound else "cell"
        if node.kind == "qualitative":
            result = observe(node.inputs[0], node.attributes["band"], ref)
        elif node.kind == "signal":
            result = observe(ref, "value", ref)
        elif node.kind == "signature":
            result = expression(node.inputs[0])
            source_map[result] = tuple(
                sorted(set(source_map[result]) | set(behavior.source_links[ref]))
            )
        elif node.kind in {"literal", "parameter"}:
            result = add(
                f"expression:{ref}",
                "constant",
                TypeSpec.from_dict(node.data_type),
                "cell",
                (ref,),
                attributes={
                    "value": node.attributes[
                        "value" if node.kind == "literal" else "default"
                    ]
                },
            )
        elif node.kind == "and" and config.conjunction_strategy == "de_morgan":
            # Rewrite the complete guard inside its original binding. Negating
            # each operand must never aggregate different contacted objects.
            negated = tuple(
                add(
                    f"expression:{ref}:not:{index}",
                    "not",
                    BOOLEAN,
                    scope,
                    (ref,),
                    inputs=(expression(item),),
                )
                for index, item in enumerate(node.inputs)
            )
            union = add(
                f"expression:{ref}:or", "or", BOOLEAN, scope, (ref,), inputs=negated
            )
            result = add(
                f"expression:{ref}", "not", BOOLEAN, scope, (ref,), inputs=(union,)
            )
        elif node.kind in {"and", "or", "not", "compare"}:
            result = add(
                f"expression:{ref}",
                node.kind,
                BOOLEAN,
                scope,
                (ref,),
                inputs=tuple(expression(item) for item in node.inputs),
                attributes={"operator": node.attributes["operator"]}
                if node.kind == "compare"
                else None,
            )
        elif node.kind == "held_for":
            result = add(
                f"expression:{ref}",
                "held_for",
                BOOLEAN,
                scope,
                (ref,),
                inputs=(expression(node.inputs[0]),),
                attributes={"duration": duration(node.inputs[1])},
            )
        elif node.kind == "became_true":
            result = add(
                f"expression:{ref}",
                "onset",
                BOOLEAN,
                scope,
                (ref,),
                inputs=(expression(node.inputs[0]),),
            )
        elif node.kind == "memory.is_set":
            result = expression(node.inputs[0])
            source_map[result] = tuple(
                sorted(set(source_map[result]) | set(behavior.source_links[ref]))
            )
            behavior_requirements[result] = tuple(
                sorted(set(behavior_requirements[result]) | set(node.requirement_ids))
            )
        elif node.kind == "memory":
            controls = dict(zip(node.attributes["input_names"], node.inputs))
            setting = expression(controls["set_when"])
            event = add(
                f"memory_onset:{ref}",
                "onset",
                BOOLEAN,
                generated[setting].scope,
                (ref,),
                inputs=(setting,),
            )
            # A new qualifying contact refreshes memory even when another
            # contact stays qualified: onset precedes existential aggregation.
            setting = aggregate(event, f"memory_set:{ref}", (ref,))
            if "reset_when" in controls:
                resetting = aggregate(
                    expression(controls["reset_when"]), f"memory_reset:{ref}", (ref,)
                )
            else:
                resetting = add(
                    f"memory_reset:{ref}",
                    "constant",
                    BOOLEAN,
                    "cell",
                    (ref,),
                    attributes={"value": False},
                )
            result = add(
                f"expression:{ref}",
                "memory",
                BOOLEAN,
                "cell",
                (ref,),
                inputs=(setting, resetting),
                attributes={
                    "duration": duration(controls["duration"])
                    if "duration" in controls
                    else None
                },
            )
        else:
            reject(f"Unsupported synthetic expression {node.kind!r}.", node)
        expression_cache[ref] = result
        return result

    outputs = []
    bindings = []
    # Declarations have automatic controls even if no output reads the latch.
    # Keep their observations, source requirements and execution in the graph.
    for memory in behavior.find(kind="memory"):
        expression(memory.id)
    for requirement in contract.requirements:
        rule = source_nodes[requirement.rule_id]
        action = source_nodes[requirement.specification_id]
        scope = "contact" if action.contact_bound else "cell"
        if (
            requirement.observable.role != domain.role
            or requirement.observable.scope != scope
        ):
            reject(
                "The response observable does not preserve its action's role/contact scope.",
                action,
            )
        guard = expression(rule.inputs[1])
        if generated[guard].scope == "contact" and scope == "cell":
            guard = add(
                f"aggregate:{requirement.id}",
                "any_contact",
                BOOLEAN,
                "cell",
                (rule.id,),
                inputs=(guard,),
                response_ids=(requirement.id,),
            )
        if action.kind == "action.pulse":
            if rule.attributes["trigger"] == "condition":
                # Cell pulses observe the onset of the complete aggregated
                # guard; contact pulses keep their own episode/onset history.
                guard = add(
                    f"pulse_onset:{requirement.id}",
                    "onset",
                    BOOLEAN,
                    scope,
                    (rule.id, action.id),
                    inputs=(guard,),
                    response_ids=(requirement.id,),
                )
            guard = add(
                f"pulse:{requirement.id}",
                "pulse",
                BOOLEAN,
                scope,
                (rule.id, action.id),
                inputs=(guard,),
                attributes={"duration": duration(action.inputs[1])},
                response_ids=(requirement.id,),
            )
        values = []
        for state, band in (
            ("active", requirement.active_range),
            ("inactive", requirement.inactive_range),
        ):
            values.append(
                add(
                    f"{state}:{requirement.id}",
                    "constant",
                    requirement.observable.dtype,
                    scope,
                    (rule.id, action.id),
                    attributes={"value": band.lower.to_dict()},
                    response_ids=(requirement.id,),
                )
            )
        selected = add(
            f"select:{requirement.id}",
            "select",
            requirement.observable.dtype,
            scope,
            (rule.id, action.id),
            inputs=(guard, *values),
            response_ids=(requirement.id,),
        )
        output = add(
            f"output:{requirement.id}",
            "output",
            requirement.observable.dtype,
            scope,
            (rule.id, action.id),
            inputs=(selected,),
            output=requirement.observable,
            response_ids=(requirement.id,),
        )
        outputs.append(output)
        bindings.append(OutputBinding(requirement.id, output))
    if observed != set(domain_inputs):
        reject(
            "Operating-domain inputs must cover exactly the supported runtime observations; extra observations are not silently ignored."
        )
    mechanism = MechanismProgram(
        f"{behavior.name}.synthetic",
        tuple(generated[key] for key in sorted(generated)),
        tuple(outputs),
        ("synthetic_signal_graph",),
    )
    return SyntheticCandidate(
        request.fingerprint,
        mechanism,
        ObservationMap(
            tuple(InputBinding(*key, input_map[key]) for key in sorted(input_map)),
            tuple(bindings),
        ),
        source_map,
        behavior_requirements,
        catalog.lock(mechanism),
        config,
    )


def generate_synthetic(request, *, config: SyntheticGeneratorConfig | None = None):
    """Propose one deterministic graph; no history or selection claim is used.

    Hard constraints apply to the actual graph. Preferences are interpreted only
    by ``select_synthetic``, which checks both bounded alternatives before ranking.
    """
    candidate = _generate_synthetic(request, config=config)
    violations = policy_for_request(
        request, candidate.generator_config.profile_version
    ).violations(candidate.mechanism)
    if violations:
        raise UnsupportedBehaviorError(
            "Synthetic proposal violates hard constraints: " + "; ".join(violations)
        )
    return candidate


def check_synthetic_candidate(
    request, candidate: SyntheticCandidate, history: Iterable[InputFrame], *, until=None
) -> CheckResult:
    """Independently check this candidate over the supplied finite history.

    Component/source metadata cannot establish behavior. A valid inventory is
    followed by ``check_realization``, which executes both independent models.
    A passing result requires exercised active and inactive deadlines for every
    response. Its dependencies include this acceptance policy, the candidate,
    request and generator configuration in addition to model execution inputs.
    """
    behavior, contract, domain, target = _request(request)
    if not isinstance(candidate, SyntheticCandidate):
        raise TypeError("Expected a SyntheticCandidate.")
    frames = tuple(history)
    catalog = catalog_for_profile(candidate.generator_config.profile_version)
    dependencies = realization_dependencies(
        behavior,
        contract,
        domain,
        target,
        candidate.mechanism,
        candidate.observation_map,
        frames,
        until=until,
    )
    dependencies = DependencySnapshot(
        {
            **dependencies.values,
            "settings": {
                **dependencies.values["settings"],
                "synthetic_acceptance": SYNTHETIC_CHECKER_VERSION,
                "synthetic_profile": candidate.generator_config.profile_version,
                "synthetic_candidate": candidate.fingerprint,
                "realization_request": request.fingerprint,
                "generator_configuration": candidate.generator_config.fingerprint,
                "catalog": catalog.fingerprint,
                "required_coverage": "active_and_inactive_deadlines_for_every_response",
            },
        }
    )

    def failure(code, message):
        return CheckResult(
            CheckOutcome.FAIL,
            dependencies,
            tuple(item.id for item in contract.requirements),
            (CheckDiagnostic(code, message),),
        )

    if candidate.request_fingerprint != request.fingerprint:
        return failure(
            "candidate_request_identity",
            "The candidate belongs to a different frozen realization request.",
        )
    try:
        violations = policy_for_request(
            request, candidate.generator_config.profile_version
        ).violations(candidate.mechanism)
    except UnsupportedBehaviorError as error:
        return CheckResult(
            CheckOutcome.UNSUPPORTED,
            dependencies,
            tuple(item.id for item in contract.requirements),
            (CheckDiagnostic("unsupported_selection_policy", str(error)),),
        )
    if violations:
        return failure("candidate_hard_constraints", "; ".join(violations))
    try:
        provenance = generate_synthetic(request, config=candidate.generator_config)
    except UnsupportedBehaviorError as error:
        return CheckResult(
            CheckOutcome.UNSUPPORTED,
            dependencies,
            tuple(item.id for item in contract.requirements),
            (
                CheckDiagnostic(
                    "unsupported_generation_profile",
                    str(error),
                    node_id=error.node_id,
                    source=error.source,
                ),
            ),
        )
    # Replay only the deterministic provenance policy. This neither compares
    # candidate edges/response values nor establishes behavioral refinement.
    if (
        candidate.source_map != provenance.source_map
        or candidate.behavior_requirement_ids != provenance.behavior_requirement_ids
    ):
        return failure(
            "candidate_lineage",
            "Source correspondence or requirement lineage differs from the declared generation profile.",
        )
    try:
        expected_locks = catalog.lock(candidate.mechanism)
    except KeyError:
        return failure(
            "candidate_component",
            "The candidate contains an operation outside its pinned synthetic catalog.",
        )
    if candidate.component_locks != expected_locks:
        return failure(
            "candidate_component",
            "The candidate's component versions or content identities are stale.",
        )
    nodes = {node.id: node for node in behavior.nodes}
    known_requirements = {item.id for item in behavior.requirements}
    for ref, lineage in candidate.source_map.items():
        if (
            set(lineage) - set(nodes)
            or set(candidate.behavior_requirement_ids[ref]) - known_requirements
        ):
            return failure(
                "candidate_lineage",
                "The candidate refers to unknown Behavior sources or requirements.",
            )
    carried_requirements = {
        item
        for values in candidate.behavior_requirement_ids.values()
        for item in values
    }
    if carried_requirements != known_requirements:
        return failure(
            "candidate_lineage",
            "The candidate does not retain every Behavior requirement.",
        )
    result = check_realization(
        behavior,
        contract,
        domain,
        target,
        candidate.mechanism,
        candidate.observation_map,
        frames,
        until=until,
    )
    return replace(result, dependencies=dependencies)

"""Finite-trace response checking against an independently executed synthetic model.

This is a bounded acceptance checker for supplied contracts and histories. It is
not universal refinement, a biological model, or an empirical validation tool.
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping
from dataclasses import dataclass
import hashlib
import json
import math
from typing import Any, ClassVar

from biocompiler.errors import BiocompilerError, SerializationError
from biocompiler.ir.behavior import BehaviorProgram
from biocompiler.ir.intent import freeze_json
from biocompiler.ir.mechanism import MechanismProgram
from biocompiler.ir.serialization import JsonArtifact
from biocompiler.models.synthetic import (
    MODEL_RUNNER_VERSION,
    ModelInputFrame,
    run_model,
)
from biocompiler.semantics.context import TargetContext
from biocompiler.semantics.evaluator import (
    InputFrame,
    REFERENCE_EVALUATOR_VERSION,
    evaluate,
)
from biocompiler.semantics.realization import BehaviorContract, OperatingDomain
from biocompiler.semantics.types import BOOLEAN, Interval, TypeSpec
from biocompiler.semantics.admission import ADMISSION_POLICY_VERSION
from biocompiler.verification.admission import admission_for_target
from biocompiler.verification.evidence import (
    CheckDiagnostic,
    CheckOutcome,
    CheckResult,
    Counterexample,
    DependencySnapshot,
    RequirementCoverage,
)

CHECKER_VERSION = "biocompiler.realization_checker.v0.3"
CHECKER_SETTINGS = freeze_json(
    {
        "scope": "supplied_contracts_and_finite_history",
        "intended_use": "software_test",
        "human_admission_policy": ADMISSION_POLICY_VERSION,
        "time": "right_continuous_piecewise_constant",
        "response": "active_inactive_bands_after_transition_deadlines",
        "nonvacuity": "checked_active_and_inactive_deadlines_for_every_response_and_complete_uncancelled_episodes",
        "contact_loss": "cancel_contact_scoped_obligations",
        "coverage": "all_selected_role_ongoing_outputs",
    }
)


def _require(ok: bool, message: str) -> None:
    if not ok:
        raise SerializationError(message)


def _name(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _fields(data: Any, expected: set[str]) -> None:
    _require(
        isinstance(data, Mapping) and set(data) == expected,
        "Invalid observation-map fields.",
    )


def _hash(data: Any) -> str:
    return hashlib.sha256(
        json.dumps(
            data, sort_keys=True, separators=(",", ":"), allow_nan=False
        ).encode()
    ).hexdigest()


@dataclass(frozen=True)
class InputBinding:
    signal_id: str
    field: str
    mechanism_input_id: str

    def __post_init__(self) -> None:
        _require(
            _name(self.signal_id) and _name(self.mechanism_input_id),
            "Input binding IDs must be nonempty.",
        )
        _require(
            isinstance(self.field, str)
            and self.field in {"value", "present", "high", "low"},
            "Unknown observation field.",
        )

    def to_dict(self) -> dict:
        return {
            "signal_id": self.signal_id,
            "field": self.field,
            "mechanism_input_id": self.mechanism_input_id,
        }

    @classmethod
    def from_dict(cls, data: Mapping) -> InputBinding:
        _fields(data, {"signal_id", "field", "mechanism_input_id"})
        return cls(**data)


@dataclass(frozen=True)
class OutputBinding:
    requirement_id: str
    mechanism_output_id: str

    def __post_init__(self) -> None:
        _require(
            _name(self.requirement_id) and _name(self.mechanism_output_id),
            "Output binding IDs must be nonempty.",
        )

    def to_dict(self) -> dict:
        return {
            "requirement_id": self.requirement_id,
            "mechanism_output_id": self.mechanism_output_id,
        }

    @classmethod
    def from_dict(cls, data: Mapping) -> OutputBinding:
        _fields(data, {"requirement_id", "mechanism_output_id"})
        return cls(**data)


@dataclass(frozen=True)
class ObservationMap(JsonArtifact):
    inputs: tuple[InputBinding, ...]
    outputs: tuple[OutputBinding, ...]
    schema_version: ClassVar[str] = "biocompiler.observation_map.v0.1"

    def __post_init__(self) -> None:
        for name, expected in (("inputs", InputBinding), ("outputs", OutputBinding)):
            values = getattr(self, name)
            _require(
                isinstance(values, (tuple, list))
                and all(isinstance(value, expected) for value in values),
                f"Invalid {name} bindings.",
            )
            object.__setattr__(self, name, tuple(values))

    def to_dict(self) -> dict:
        return {
            "schema_version": self.schema_version,
            "inputs": [item.to_dict() for item in self.inputs],
            "outputs": [item.to_dict() for item in self.outputs],
        }

    @classmethod
    def from_dict(cls, data: Mapping) -> ObservationMap:
        _fields(data, {"schema_version", "inputs", "outputs"})
        _require(
            data["schema_version"] == cls.schema_version,
            "Unsupported observation-map schema.",
        )
        _require(
            isinstance(data["inputs"], (list, tuple))
            and isinstance(data["outputs"], (list, tuple)),
            "Bindings must be arrays.",
        )
        return cls(
            tuple(InputBinding.from_dict(item) for item in data["inputs"]),
            tuple(OutputBinding.from_dict(item) for item in data["outputs"]),
        )


def _horizon(history: tuple[InputFrame, ...], until: Any) -> float | int:
    horizon = (history[-1].time if history else 0) if until is None else until
    try:
        valid = (
            type(horizon) in (int, float) and math.isfinite(horizon) and horizon >= 0
        )
    except (OverflowError, ValueError):
        valid = False
    if not valid:
        raise ValueError("Evaluation horizon must be a nonnegative finite number.")
    return horizon


def realization_dependencies(
    behavior: BehaviorProgram,
    contract: BehaviorContract,
    domain: OperatingDomain,
    target: TargetContext,
    mechanism: MechanismProgram,
    observation_map: ObservationMap,
    history: Iterable[InputFrame],
    *,
    until: float | int | None = None,
) -> DependencySnapshot:
    """Recompute the complete dependency identity without re-running the models."""
    frames = tuple(history)
    if any(not isinstance(frame, InputFrame) for frame in frames):
        raise TypeError("History must contain InputFrame objects.")
    return DependencySnapshot(
        {
            "behavior": behavior.fingerprint,
            "behavior_artifact": _hash(behavior.to_dict()),
            "contract": contract.fingerprint,
            "domain": domain.fingerprint,
            "target": target.fingerprint,
            "mechanism": mechanism.fingerprint,
            "observation_map": observation_map.fingerprint,
            "history": _hash([frame.to_dict() for frame in frames]),
            "horizon": {"until": until, "effective": _horizon(frames, until)},
            "checker": CHECKER_VERSION,
            "model_runner": MODEL_RUNNER_VERSION,
            "reference_evaluator": REFERENCE_EVALUATOR_VERSION,
            "settings": {**CHECKER_SETTINGS, "max_microsteps": 1000},
        }
    )


def _runtime_observations(behavior: BehaviorProgram, role: str) -> set[tuple[str, str]]:
    nodes = {node.id: node for node in behavior.nodes}
    pending = [ref for ref in behavior.roots if nodes[ref].role in (None, role)]
    live = set()
    while pending:
        ref = pending.pop()
        if ref in live:
            continue
        live.add(ref)
        node = nodes[ref]
        pending.extend(node.inputs[:1] if node.kind == "signature" else node.inputs)
    required = set()
    for ref in live:
        node = nodes[ref]
        if node.role not in (None, role):
            continue
        if node.kind == "qualitative":
            required.add((node.inputs[0], node.attributes["band"]))
        elif node.kind not in {"signature", "scope", "role"}:
            required.update(
                (item, "value") for item in node.inputs if nodes[item].kind == "signal"
            )
    return required


def _same_observable(left: Any, right: Any) -> bool:
    return left.to_dict() == right.to_dict()


def _contains(interval: Interval, value: Any) -> bool:
    return (
        type(value) in (int, float)
        and math.isfinite(value)
        and interval.lower.canonical_value <= value <= interval.upper.canonical_value
    )


def check_realization(
    behavior: BehaviorProgram,
    contract: BehaviorContract,
    domain: OperatingDomain,
    target: TargetContext,
    mechanism: MechanismProgram,
    observation_map: ObservationMap,
    history: Iterable[InputFrame],
    *,
    until: float | int | None = None,
) -> CheckResult:
    """Check active/inactive response envelopes on the supplied finite history.

    Contacts preserve identity. Disappearance cancels their pending obligations;
    reappearance begins a new episode. Unexercised active or inactive responses
    and incomplete episodes yield UNKNOWN, never a vacuous PASS. Input-domain failures are UNKNOWN; structurally
    wrong mappings and observed violations are FAIL. Unsupported profiles remain
    explicit. No solver search, sequence generation or empirical claim is made.
    """
    for value, expected in (
        (behavior, BehaviorProgram),
        (contract, BehaviorContract),
        (domain, OperatingDomain),
        (target, TargetContext),
        (mechanism, MechanismProgram),
        (observation_map, ObservationMap),
    ):
        if not isinstance(value, expected):
            raise TypeError(
                f"Expected {expected.__name__}, got {type(value).__name__}."
            )
    frames = tuple(history)
    deps = realization_dependencies(
        behavior,
        contract,
        domain,
        target,
        mechanism,
        observation_map,
        frames,
        until=until,
    )
    horizon = _horizon(frames, until)
    requirements = {item.id: item for item in contract.requirements}
    ids = tuple(requirements)
    nodes = {node.id: node for node in behavior.nodes}
    model_nodes = {node.id: node for node in mechanism.nodes}
    diagnostics = []

    def result(
        outcome, code=None, message=None, *, requirement=None, node=None, examples=()
    ):
        entries = list(diagnostics)
        if code:
            entries.append(
                CheckDiagnostic(
                    code,
                    message,
                    requirement,
                    node.id if node else None,
                    node.source if node else None,
                )
            )
        return CheckResult(outcome, deps, ids, tuple(entries), tuple(examples))

    admission = admission_for_target(target, boundary="verification")
    if admission.decision != "software_only":
        return result(
            CheckOutcome.UNSUPPORTED,
            "human_profile_not_admitted",
            "; ".join(admission.diagnostics),
        )

    if contract.behavior_fingerprint != behavior.fingerprint:
        return result(
            CheckOutcome.FAIL,
            "behavior_identity",
            "The response contract refers to a different BehaviorProgram.",
        )
    if domain.role not in nodes or nodes[domain.role].kind != "role":
        return result(
            CheckOutcome.FAIL,
            "role_identity",
            "OperatingDomain.role must identify an exact behavior role node.",
        )
    domain_inputs = {(item.signal_id, item.field): item for item in domain.inputs}
    if set(domain_inputs) != _runtime_observations(behavior, domain.role):
        return result(
            CheckOutcome.FAIL,
            "input_domain_coverage",
            "Operating-domain inputs must cover exactly the selected role's runtime observations, excluding unused signature metadata.",
        )
    inputs = {(item.signal_id, item.field): item for item in observation_map.inputs}
    if len(inputs) != len(observation_map.inputs) or set(inputs) != set(domain_inputs):
        return result(
            CheckOutcome.FAIL,
            "input_binding_coverage",
            "Input bindings must cover the operating-domain observations exactly once.",
        )
    model_input_ids = {node.id for node in mechanism.nodes if node.kind == "input"}
    mapped_input_ids = [item.mechanism_input_id for item in observation_map.inputs]
    if (
        len(set(mapped_input_ids)) != len(mapped_input_ids)
        or set(mapped_input_ids) != model_input_ids
    ):
        return result(
            CheckOutcome.FAIL,
            "model_input_coverage",
            "Every model input must have one distinct observation binding.",
        )
    for key, item in domain_inputs.items():
        source = nodes.get(item.signal_id)
        if source is None or source.kind != "signal" or source.role != domain.role:
            return result(
                CheckOutcome.FAIL,
                "input_source",
                "Input domain does not identify a signal owned by the selected role.",
            )
        expected_type = (
            TypeSpec.from_dict(source.data_type) if item.field == "value" else BOOLEAN
        )
        if (
            item.observable.role != domain.role
            or item.observable.scope != ("contact" if source.contact_bound else "cell")
            or not item.observable.dtype.compatible(expected_type)
        ):
            return result(
                CheckOutcome.FAIL,
                "input_semantics",
                "Input endpoint role, scope, or type differs from the authored observation.",
                node=source,
            )
        port = model_nodes[inputs[key].mechanism_input_id]
        if not _same_observable(item.observable, port.output):
            return result(
                CheckOutcome.FAIL,
                "input_endpoint",
                "Model input must match the domain's explicit endpoint identity, role, scope, compartment and type.",
                node=source,
            )
    outputs = {item.requirement_id: item for item in observation_map.outputs}
    mapped_output_ids = [item.mechanism_output_id for item in observation_map.outputs]
    if (
        len(outputs) != len(observation_map.outputs)
        or set(outputs) != set(requirements)
        or len(set(mapped_output_ids)) != len(mapped_output_ids)
        or set(mapped_output_ids) != set(mechanism.outputs)
    ):
        return result(
            CheckOutcome.FAIL,
            "output_binding_coverage",
            "Output bindings must match every requirement and declared model output one-to-one.",
        )
    for node in mechanism.nodes:
        if set(node.requirement_ids) - set(requirements):
            return result(
                CheckOutcome.FAIL,
                "unknown_model_requirement",
                f"Mechanism node {node.id!r} refers to an unknown response requirement.",
            )
    pairs = set()
    for requirement in requirements.values():
        rule = nodes.get(requirement.rule_id)
        specification = nodes.get(requirement.specification_id)
        if (
            rule is None
            or rule.kind != "rule"
            or rule.role != domain.role
            or specification is None
            or specification.id not in rule.inputs[2:]
        ):
            return result(
                CheckOutcome.FAIL,
                "requirement_source",
                "Response requirement must identify an installed rule and its exact action specification.",
                requirement=requirement.id,
            )
        pair = (rule.id, specification.id)
        if pair in pairs:
            return result(
                CheckOutcome.FAIL,
                "duplicate_response",
                "One action specification in one rule must have one response requirement.",
                requirement=requirement.id,
                node=rule,
            )
        pairs.add(pair)
        primitive = (
            nodes[specification.inputs[0]]
            if specification.kind == "action.pulse"
            else specification
        )
        if not primitive.attributes.get("ongoing"):
            return result(
                CheckOutcome.UNSUPPORTED,
                "instantaneous_response",
                "This profile checks ongoing requests and explicit pulses, not instantaneous reactions.",
                requirement=requirement.id,
                node=specification,
            )
        if (
            primitive.kind == "action.secrete"
            and primitive.attributes.get("rate") == "expression"
        ):
            return result(
                CheckOutcome.UNSUPPORTED,
                "quantitative_action_law",
                "A dynamic requested output rate needs a quantitative tracking contract beyond activation bands.",
                requirement=requirement.id,
                node=specification,
            )
        expected_scope = "contact" if specification.contact_bound else "cell"
        if (
            requirement.observable.role != domain.role
            or requirement.observable.scope != expected_scope
        ):
            return result(
                CheckOutcome.FAIL,
                "output_semantics",
                "Response endpoint role and scope must match the installed action.",
                requirement=requirement.id,
                node=specification,
            )
        model_output = model_nodes.get(outputs[requirement.id].mechanism_output_id)
        if (
            model_output is None
            or model_output.kind != "output"
            or not _same_observable(requirement.observable, model_output.output)
        ):
            return result(
                CheckOutcome.FAIL,
                "output_endpoint",
                "Model output must match the response's exact endpoint identity, role, scope, compartment and type.",
                requirement=requirement.id,
                node=specification,
            )
        if requirement.id not in model_output.requirement_ids:
            return result(
                CheckOutcome.FAIL,
                "missing_output_lineage",
                "Mapped model output must retain its response requirement identity.",
                requirement=requirement.id,
                node=specification,
            )
    installed = set()
    for rule in behavior.find(kind="rule", role=domain.role):
        for ref in rule.inputs[2:]:
            action = nodes[ref]
            if action.attributes.get("ongoing"):
                installed.add((rule.id, ref))
            elif action.kind != "action.state_set":
                return result(
                    CheckOutcome.UNSUPPORTED,
                    "instantaneous_output",
                    "The selected role has instantaneous output requests outside this response profile.",
                    node=action,
                )
    if pairs != installed:
        return result(
            CheckOutcome.UNSUPPORTED,
            "uncontracted_outputs",
            "The contract must cover every installed ongoing output of the selected role; this profile does not silently accept partial output coverage.",
        )
    capabilities = set(domain.required_capabilities) | set(
        mechanism.required_capabilities
    )
    if capabilities - set(target.capabilities):
        return result(
            CheckOutcome.FAIL,
            "missing_capabilities",
            "Target lacks declared capabilities: "
            + ", ".join(sorted(capabilities - set(target.capabilities))),
        )
    compartments = {node.output.compartment for node in mechanism.nodes}
    if compartments - set(target.compartments):
        return result(
            CheckOutcome.FAIL,
            "missing_compartments",
            "Target does not declare every model endpoint compartment.",
        )
    if any(node.output.role != domain.role for node in mechanism.nodes):
        return result(
            CheckOutcome.UNSUPPORTED,
            "multiple_model_roles",
            "This checker executes one engineered-cell role per finite trace.",
        )
    if not frames:
        return result(
            CheckOutcome.UNKNOWN,
            "empty_history",
            "No input history was supplied; no response was exercised.",
        )
    if frames[0].time != 0 or any(
        right.time <= left.time for left, right in zip(frames, frames[1:])
    ):
        return result(
            CheckOutcome.UNKNOWN,
            "invalid_history",
            "Input snapshots must start at zero and have strictly increasing timestamps.",
        )
    for frame in frames:
        if frame.time > horizon:
            continue
        if (
            domain.max_contacts is not None
            and len(frame.contacts) > domain.max_contacts
        ):
            return result(
                CheckOutcome.UNKNOWN,
                "outside_domain",
                "Input history exceeds the domain's maximum simultaneous contacts.",
            )
        for item in domain.inputs:
            samples = (
                list(frame.contacts.values())
                if item.scope == "contact"
                else [frame.signals]
            )
            for sample_set in samples:
                sample = sample_set.get(item.signal_id)
                value = getattr(sample, item.field, None)
                allowed = (
                    _contains(item.allowed, value)
                    if isinstance(item.allowed, Interval)
                    else type(value) is bool and value in item.allowed
                )
                if not allowed:
                    return result(
                        CheckOutcome.UNKNOWN,
                        "outside_domain",
                        f"Missing or out-of-domain {item.field} observation at time {frame.time}.",
                        node=nodes[item.signal_id],
                    )
    model_history = []
    for frame in frames:
        if frame.time > horizon:
            continue
        values, contacts = {}, {identity: {} for identity in frame.contacts}
        for key, binding in inputs.items():
            item = domain_inputs[key]
            if item.scope == "cell":
                values[binding.mechanism_input_id] = getattr(
                    frame.signals[item.signal_id], item.field
                )
            else:
                for identity, samples in frame.contacts.items():
                    contacts[identity][binding.mechanism_input_id] = getattr(
                        samples[item.signal_id], item.field
                    )
        model_history.append(ModelInputFrame(frame.time, values, contacts))
    try:
        desired = evaluate(behavior, frames, role=domain.role, until=horizon)
        actual = run_model(mechanism, model_history, until=horizon)
    except BiocompilerError as exc:
        return result(
            CheckOutcome.UNKNOWN,
            "execution_unavailable",
            f"The supplied history could not be evaluated: {exc}",
        )
    except (ValueError, ArithmeticError) as exc:
        return result(
            CheckOutcome.UNKNOWN,
            "execution_unavailable",
            f"The supplied history could not be evaluated: {exc}",
        )
    return _monitor(
        behavior,
        contract,
        domain,
        observation_map,
        frames,
        desired,
        actual,
        deps,
        horizon,
    )


def _at(frames, time):
    current = frames[0]
    for frame in frames[1:]:
        if frame.time > time:
            break
        current = frame
    return current


def _monitor(
    behavior,
    contract,
    domain,
    observation_map,
    history,
    desired,
    actual,
    dependencies,
    horizon,
):
    nodes = {node.id: node for node in behavior.nodes}
    outputs = {
        binding.requirement_id: binding.mechanism_output_id
        for binding in observation_map.outputs
    }
    base_times = sorted(
        {
            0,
            horizon,
            *(frame.time for frame in desired.frames),
            *(frame.time for frame in actual.frames),
            *(frame.time for frame in history if frame.time <= horizon),
        }
    )
    diagnostics, counterexamples = [], []
    requirements = tuple(item.id for item in contract.requirements)
    active_covered = {item.id: False for item in contract.requirements}
    counts = {
        item.id: {
            "activation_deadlines_checked": 0,
            "inactive_deadlines_checked": 0,
            "incomplete_episode_count": 0,
            "cancelled_episode_count": 0,
        }
        for item in contract.requirements
    }
    incomplete = set()
    if horizon < domain.minimum_horizon.canonical_value:
        diagnostics.append(
            CheckDiagnostic(
                "short_horizon",
                "The supplied horizon is shorter than the operating domain's required observation interval.",
            )
        )
    for requirement in contract.requirements:
        # Each contact appearance starts a new episode. Entries track desired
        # state, its onset and whether that active/inactive deadline was checked.
        episodes = {}
        times = set(base_times)
        processed = set()
        while times - processed:
            time = min(times - processed)
            processed.add(time)
            input_frame = _at(history, time)
            bindings = (
                set(input_frame.contacts)
                if requirement.observable.scope == "contact"
                else {None}
            )
            for vanished in set(episodes) - bindings:
                # Contact loss cancels pending obligations for that episode.
                if not episodes[vanished][2]:
                    counts[requirement.id]["cancelled_episode_count"] += 1
                del episodes[vanished]
            requests = _at(desired.frames, time).actions
            model_frame = _at(actual.frames, time)
            for binding in sorted(
                bindings, key=lambda value: "" if value is None else value
            ):
                enabled = any(
                    item.rule_id == requirement.rule_id
                    and item.specification_id == requirement.specification_id
                    and item.contact_id == binding
                    for item in requests
                )
                previous = episodes.get(binding)
                if previous is None or previous[0] != enabled:
                    if previous is not None and not previous[2]:
                        incomplete.add(requirement.id)
                        counts[requirement.id]["incomplete_episode_count"] += 1
                    delay = (
                        requirement.max_activation_delay
                        if enabled
                        else requirement.max_deactivation_delay
                    )
                    deadline = time + delay.canonical_value
                    if (
                        not math.isfinite(deadline)
                        or delay.canonical_value > 0
                        and deadline <= time
                    ):
                        diagnostics.append(
                            CheckDiagnostic(
                                "numeric_resolution",
                                "A response delay cannot be represented as a finite later deadline at this timestamp.",
                                requirement.id,
                                requirement.specification_id,
                                nodes[requirement.specification_id].source,
                            )
                        )
                        deadline = math.inf
                    episodes[binding] = [enabled, deadline, False]
                    if deadline <= horizon:
                        times.add(deadline)
                episode = episodes[binding]
                if time < episode[1]:
                    continue
                interval = (
                    requirement.active_range if enabled else requirement.inactive_range
                )
                samples = (
                    model_frame.values
                    if binding is None
                    else model_frame.contacts.get(binding, {})
                )
                value = samples.get(outputs[requirement.id])
                if not episode[2]:
                    counts[requirement.id][
                        "activation_deadlines_checked"
                        if enabled
                        else "inactive_deadlines_checked"
                    ] += 1
                    episode[2] = True
                if enabled:
                    active_covered[requirement.id] = True
                if not _contains(interval, value):
                    counterexamples.append(
                        Counterexample(
                            requirement.id,
                            time,
                            binding,
                            {
                                "state": "active" if enabled else "inactive",
                                "range": interval.to_dict(),
                            },
                            value,
                            requirement.rule_id,
                            requirement.specification_id,
                            nodes[requirement.specification_id].source,
                        )
                    )
        if any(not entry[2] for entry in episodes.values()):
            incomplete.add(requirement.id)
            counts[requirement.id]["incomplete_episode_count"] += sum(
                not entry[2] for entry in episodes.values()
            )
    coverage = tuple(
        RequirementCoverage(item.id, **counts[item.id])
        for item in contract.requirements
    )
    if counterexamples:
        diagnostics.append(
            CheckDiagnostic(
                "response_violation",
                "Independent model outputs violate one or more response envelopes after their deadlines.",
            )
        )
        return CheckResult(
            CheckOutcome.FAIL,
            dependencies,
            requirements,
            tuple(diagnostics),
            tuple(counterexamples),
            coverage=coverage,
        )
    for requirement in contract.requirements:
        if not active_covered[requirement.id]:
            diagnostics.append(
                CheckDiagnostic(
                    "unexercised_response",
                    "No active response deadline was exercised for this requirement.",
                    requirement.id,
                    requirement.specification_id,
                    nodes[requirement.specification_id].source,
                )
            )
        if counts[requirement.id]["inactive_deadlines_checked"] == 0:
            diagnostics.append(
                CheckDiagnostic(
                    "unexercised_inactive_response",
                    "No inactive response deadline was exercised for this requirement.",
                    requirement.id,
                    requirement.specification_id,
                    nodes[requirement.specification_id].source,
                )
            )
        if requirement.id in incomplete:
            diagnostics.append(
                CheckDiagnostic(
                    "incomplete_episode",
                    "A response episode ended or the horizon was reached before its response deadline could be checked.",
                    requirement.id,
                    requirement.specification_id,
                    nodes[requirement.specification_id].source,
                )
            )
    outcome = CheckOutcome.UNKNOWN if diagnostics else CheckOutcome.PASS
    return CheckResult(
        outcome, dependencies, requirements, tuple(diagnostics), coverage=coverage
    )
